document.addEventListener("DOMContentLoaded",()=>{window.hljs&&document.querySelectorAll('.article-body pre code[class*="language-"]:not(.language-text)').forEach(e=>{window.hljs.highlightElement(e)}),document.querySelectorAll(".share-copy").forEach(e=>{e.addEventListener("click",async()=>{const t=e.dataset.copyUrl;try{await navigator.clipboard.writeText(t);const o=e.querySelector("svg");e.setAttribute("aria-label","Article link copied"),e.setAttribute("title","Article link copied"),o&&o.setAttribute("data-lucide","check"),window.lucide&&window.lucide.createIcons(),setTimeout(()=>{e.setAttribute("aria-label","Copy article link"),e.setAttribute("title","Copy article link"),o&&o.setAttribute("data-lucide","link"),window.lucide&&window.lucide.createIcons()},1800)}catch(t){e.setAttribute("title","Copy failed")}})});document.querySelectorAll(".code-copy-btn").forEach(e=>{e.addEventListener("click",()=>{const t=e.closest(".code-block-wrapper").querySelector("code");t&&navigator.clipboard.writeText(t.innerText).then(()=>{const t=e.innerText;e.innerText="Copied!",e.classList.add("copied"),setTimeout(()=>{e.innerText=t,e.classList.remove("copied")},2e3)}).catch(e=>{console.error("Failed to copy text: ",e)})})}),document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",function(e){const t=this.getAttribute("href");if("#"===t)return;const o=document.querySelector(t);if(o){e.preventDefault();const t=80,c=o.getBoundingClientRect().top+window.pageYOffset-t;window.scrollTo({top:c,behavior:"smooth"})}})})});